/* SPDX-License-Identifier: GPL-3.0-or-later
 * Strict bounded reader derived from the format interpretation in pkgpfs.py
 * (OpenOrbis LibOrbisPkg port), using ps4mount's package metadata/crypto API.
 * No source writes, no implicit zero filling, no retail/passcode recovery.
 */
#include "extract_reader.h"
#include "vendor/pkg.h"
#include "vendor/crypto.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdarg.h>
#include <unistd.h>
#include <sys/stat.h>
#include <zlib.h>
#define MAX_INODES 100000u
#define MAX_BLOCKS 8388608u
#define MAX_FILES 100000u
#define MAX_PATH 1024u
#define MAX_BS 1048576u
#define MAX_MAP 8388608u

typedef struct stream stream;
typedef int (*reader_fn)(stream *,uint64_t,void *,size_t);
struct stream { uint64_t size; reader_fn fn; void *ctx; };
typedef struct { uint64_t size,csize; uint32_t flags,blocks; uint16_t mode; int32_t db[12],ib[5]; uint32_t *map; } inode;
typedef struct { stream s,*source; uint32_t bs; uint64_t count; uint64_t *map; uint8_t *cache,*compressed; uint64_t cached; } pfsc;
typedef struct { stream *r; uint32_t bs,n; int sig; inode *nodes; struct fl_pkg_reader *owner; } pfs;
typedef struct { stream s; pfs *fs; inode *node; } file_stream;
typedef struct { stream s; stream *source; uint8_t key[32],cache[65536]; uint64_t cached,start; size_t cached_len; } xts;
struct fl_pkg_reader { pkg_t pkg; uint64_t physical_size,base; stream raw; xts crypt; pfs outer,inner; file_stream image; pfsc image_pfsc,active_pfsc; file_stream active_file; size_t active_index; fl_pkg_file *files; size_t count,capacity; uint64_t map_bytes; uint8_t *visiting; char error[256]; };
static uint16_t l16(const uint8_t *p){return (uint16_t)(p[0]|p[1]<<8);}
static uint32_t l32(const uint8_t *p){return (uint32_t)p[0]|(uint32_t)p[1]<<8|(uint32_t)p[2]<<16|(uint32_t)p[3]<<24;}
static uint64_t l64(const uint8_t *p){return l32(p)|((uint64_t)l32(p+4)<<32);}
static uint64_t b64(const uint8_t *p){uint64_t x=0;for(int i=0;i<8;i++)x=(x<<8)|p[i];return x;}
static int fail(fl_pkg_reader *r,const char *fmt,...){va_list ap;va_start(ap,fmt);vsnprintf(r->error,sizeof(r->error),fmt,ap);va_end(ap);return -1;}
static int within(uint64_t total,uint64_t pos,uint64_t n){return pos<=total&&n<=total-pos;}
static int rd(stream *s,uint64_t p,void *b,size_t n){return !within(s->size,p,n)?-1:s->fn(s,p,b,n);}
static int raw_read(stream *s,uint64_t p,void *b,size_t n){fl_pkg_reader *r=s->ctx;uint8_t *q=b;while(n){ssize_t z=pread(r->pkg.fd,q,n,(off_t)(r->base+p));if(z<=0)return fail(r,"Source read failed");q+=z;p+=(uint64_t)z;n-=(size_t)z;}return 0;}
static int xts_read(stream *s,uint64_t p,void *out,size_t n){xts *x=s->ctx;uint8_t *o=out;while(n){uint64_t ci=p/65536;size_t off=(size_t)(p%65536);if(x->cached!=ci){uint64_t at=ci*65536;size_t len=(size_t)(x->source->size-at);if(len>65536)len=65536;if(len%4096||rd(x->source,at,x->cache,len))return -1;for(size_t k=0;k<len;k+=4096){uint64_t sec=at/4096+k/4096;if(sec>=x->start&&fl_aes128_xts_decrypt(x->key+16,x->key,sec,x->cache+k,4096))return -1;}x->cached=ci;x->cached_len=len;}size_t k=x->cached_len-off;if(k>n)k=n;memcpy(o,x->cache+off,k);o+=k;p+=k;n-=k;}return 0;}
static int block_valid(pfs *p,int32_t b){return b>0&&(uint64_t)(uint32_t)b<p->r->size/p->bs;}
static int append_indirect(pfs *p,int32_t block,unsigned level,uint32_t *map,uint32_t *used,uint32_t want){if(!block_valid(p,block)||!level||level>5)return -1;uint8_t *buf=malloc(p->bs);if(!buf)return -1;if(rd(p->r,(uint64_t)(uint32_t)block*p->bs,buf,p->bs)){free(buf);return -1;}uint32_t step=p->sig?36:4,offset=p->sig?32:0;for(uint32_t k=0;k<p->bs/step&&*used<want;k++){int32_t b=(int32_t)l32(buf+k*step+offset);if(level==1){if(!block_valid(p,b)){free(buf);return -1;}map[(*used)++]=(uint32_t)b;}else if(append_indirect(p,b,level-1,map,used,want)){free(buf);return -1;}}free(buf);return 0;}
static int make_map(pfs *p,inode *d){if(d->map||!d->blocks)return 0;if(d->blocks>MAX_BLOCKS||!block_valid(p,d->db[0]))return fail(p->owner,"Invalid PFS block count/address");if(p->owner->map_bytes+(uint64_t)d->blocks*4>64*1024*1024)return fail(p->owner,"PFS allocation maps exceed 64 MiB limit");d->map=malloc((size_t)d->blocks*4);p->owner->map_bytes+=(uint64_t)d->blocks*4;if(!d->map)return fail(p->owner,"PFS map allocation failed");if(d->blocks==1||d->db[1]==-1){if(!within(p->r->size/p->bs,(uint32_t)d->db[0],d->blocks))return fail(p->owner,"Contiguous PFS range exceeds source");for(uint32_t i=0;i<d->blocks;i++)d->map[i]=(uint32_t)d->db[0]+i;return 0;}uint32_t used=0;for(uint32_t i=0;i<12&&used<d->blocks;i++){if(!block_valid(p,d->db[i]))return fail(p->owner,"Invalid direct PFS block");d->map[used++]=(uint32_t)d->db[i];}for(unsigned level=1;level<=5&&used<d->blocks;level++)if(append_indirect(p,d->ib[level-1],level,d->map,&used,d->blocks))return fail(p->owner,"Invalid PFS indirect block tree");return used==d->blocks?0:fail(p->owner,"PFS block list incomplete");}
static int file_read(stream *s,uint64_t pos,void *out,size_t n){file_stream *f=s->ctx;pfs *p=f->fs;inode *d=f->node;if(make_map(p,d))return -1;uint8_t *o=out;while(n){uint64_t i=pos/p->bs;if(i>=d->blocks)return fail(p->owner,"File exceeds PFS block list");size_t off=(size_t)(pos%p->bs),k=p->bs-off;if(k>n)k=n;if(rd(p->r,(uint64_t)d->map[i]*p->bs+off,o,k))return -1;o+=k;pos+=k;n-=k;}return 0;}
static void file_init(file_stream *f,pfs *p,uint32_t ino){memset(f,0,sizeof(*f));f->fs=p;f->node=&p->nodes[ino];f->s=(stream){f->node->size,file_read,f};}
static void pfsc_free(pfsc *p){free(p->map);free(p->cache);free(p->compressed);memset(p,0,sizeof(*p));}
static voidpf fl_zalloc(voidpf opaque,uInt count,uInt size){(void)opaque;if(size&&count>SIZE_MAX/size)return NULL;return calloc(count,size);}
static void fl_zfree(voidpf opaque,voidpf ptr){(void)opaque;free(ptr);}
static int pfsc_read(stream *s,uint64_t pos,void *out,size_t n){pfsc *p=s->ctx;uint8_t *o=out;while(n){uint64_t i=pos/p->bs;if(p->cached!=i){uint64_t a=p->map[i],sz=p->map[i+1]-a;size_t expected=(size_t)((p->s.size-i*p->bs)<p->bs?p->s.size-i*p->bs:p->bs);if(sz==p->bs){if(rd(p->source,a,p->cache,p->bs))return -1;}else{if(!sz||sz>p->bs||rd(p->source,a,p->compressed,(size_t)sz))return -1;z_stream z;memset(&z,0,sizeof(z));z.zalloc=fl_zalloc;z.zfree=fl_zfree;z.next_in=p->compressed;z.avail_in=(uInt)sz;z.next_out=p->cache;z.avail_out=p->bs;if(inflateInit(&z)!=Z_OK)return -1;int rc=inflate(&z,Z_FINISH);int good=rc==Z_STREAM_END&&z.total_in==sz&&z.total_out==expected;inflateEnd(&z);if(!good)return -1;}p->cached=i;}size_t off=(size_t)(pos%p->bs),k=p->bs-off;if(k>n)k=n;memcpy(o,p->cache+off,k);o+=k;pos+=k;n-=k;}return 0;}
static int pfsc_init(pfsc *p,stream *src){uint8_t h[48];memset(p,0,sizeof(*p));if(rd(src,0,h,48)||l32(h)!=0x43534650)return -1;uint32_t bs=l32(h+12);uint64_t bs2=l64(h+16),mo=l64(h+24),ds=l64(h+32),size=l64(h+40);if(bs<4096||bs>MAX_BS||bs2!=bs||size>INT64_MAX)return -1;uint64_t count=size/bs+(size%bs!=0);if(!count||count>=MAX_MAP||!within(src->size,mo,(count+1)*8)||ds>src->size)return -1;p->map=malloc((size_t)(count+1)*8);p->cache=malloc(bs);p->compressed=malloc(bs);if(!p->map||!p->cache||!p->compressed)goto bad;for(uint64_t i=0;i<=count;i++){uint8_t b[8];if(rd(src,mo+i*8,b,8))goto bad;p->map[i]=l64(b);if(p->map[i]>src->size||(i&&p->map[i]<=p->map[i-1])||(!i&&(p->map[i]<ds||p->map[i]<mo+(count+1)*8))||(i&&p->map[i]-p->map[i-1]>bs))goto bad;}p->source=src;p->bs=bs;p->count=count;p->cached=UINT64_MAX;p->s=(stream){size,pfsc_read,p};return 0;bad:pfsc_free(p);return -1;}
static int pfs_init(pfs *p,fl_pkg_reader *owner,stream *src,const uint8_t *ek,int newcrypt){uint8_t h[1024];memset(p,0,sizeof(*p));p->owner=owner;if(rd(src,0,h,sizeof(h))||l64(h)!=1||l64(h+8)!=20130315)return fail(owner,"Invalid PFS header");uint16_t mode=l16(h+28);p->bs=l32(h+32);uint64_t ni=l64(h+48),nb=l64(h+64);if(p->bs<4096||p->bs>MAX_BS||(p->bs&(p->bs-1))||!ni||ni>MAX_INODES||nb>MAX_INODES)return fail(owner,"Unsupported PFS dimensions");p->sig=!!(mode&1);p->n=(uint32_t)ni;p->r=src;if(mode&4){if(!ek)return fail(owner,"Unsupported encrypted inner PFS");xts *x=&owner->crypt;x->source=src;x->start=p->bs/4096;x->cached=UINT64_MAX;uint8_t key[32],msg[20]={1};memcpy(key,ek,32);if(newcrypt)fl_hmac_sha256(ek,32,h+0x370,16,key);memcpy(msg+4,h+0x370,16);fl_hmac_sha256(key,32,msg,20,x->key);x->s=(stream){src->size,xts_read,x};p->r=&x->s;}unsigned nind=0;for(unsigned i=0;i<5;i++)if(l64(h+0x298+i*40+32)>0)nind++;uint32_t dsz=p->sig?0x2c8:0xa8,per=p->bs/dsz;uint64_t start=(uint64_t)p->bs*(1+nind);if(!per||nb<(ni+per-1)/per||!within(src->size,start,nb*p->bs))return fail(owner,"Invalid PFS inode table bounds");p->nodes=calloc((size_t)ni,sizeof(inode));if(!p->nodes)return -1;uint8_t *block=malloc(p->bs);if(!block)return -1;for(uint32_t i=0;i<ni;i++){if(i%per==0&&rd(p->r,start+(uint64_t)(i/per)*p->bs,block,p->bs)){free(block);return fail(owner,"PFS inode read failed");}const uint8_t *b=block+(i%per)*dsz;inode *d=&p->nodes[i];d->mode=l16(b);d->flags=l32(b+4);d->size=l64(b+8);d->csize=l64(b+16);d->blocks=l32(b+96);if(d->size>INT64_MAX||d->csize>INT64_MAX||d->blocks>MAX_BLOCKS||d->size>(uint64_t)d->blocks*p->bs){free(block);return fail(owner,"Invalid PFS inode length");}for(unsigned k=0;k<17;k++){uint32_t off=p->sig?100+k*36+32:100+k*4;int32_t v=(int32_t)l32(b+off);if(k<12)d->db[k]=v;else d->ib[k-12]=v;}}free(block);return 0;}
static int walk(pfs *p,uint32_t ino,const char *prefix,unsigned depth,int top){fl_pkg_reader *r=p->owner;if(ino>=p->n||depth>32||r->visiting[ino])return fail(r,"Invalid/cyclic PFS directory");r->visiting[ino]=1;inode *d=&p->nodes[ino];if((d->mode&0170000)!=0040000||d->size>16*1024*1024)return fail(r,"Unsupported PFS directory");file_stream fs;file_init(&fs,p,ino);uint8_t *buf=malloc(p->bs);if(!buf)return -1;for(uint64_t at=0;at<d->size;at+=p->bs){size_t len=(size_t)(d->size-at);if(len>p->bs)len=p->bs;if(rd(&fs.s,at,buf,len))goto bad;size_t pos=0;while(pos<len){if(len-pos<16)goto bad;const uint8_t *b=buf+pos;uint32_t in=l32(b),ty=l32(b+4),nl=l32(b+8),es=l32(b+12);if(!es)break;if(es<16||es>len-pos||nl>es-16||!nl||nl>255||in>=p->n)goto bad;char name[256];memcpy(name,b+16,nl);name[nl]=0;if(memchr(name,0,nl))goto bad;if((ty==4&&!strcmp(name,"."))||(ty==5&&!strcmp(name,".."))){pos+=es;continue;}if(memchr(name,0,nl)||strchr(name,'/')||strchr(name,'\\')||!strcmp(name,".")||!strcmp(name,".."))goto bad;char path[MAX_PATH];int plen=snprintf(path,sizeof(path),"%s%s",prefix,name);if(plen<0||(size_t)plen>=sizeof(path))goto bad;if(ty==3){if(top){if(!strcmp(name,"uroot")&&walk(p,in,"",depth+1,0))goto bad;}else{if((size_t)plen+1>=sizeof(path))goto bad;strcat(path,"/");if(walk(p,in,path,depth+1,0))goto bad;}}else if(ty==2&&!top){if(r->count>=MAX_FILES)goto bad;if(r->count==r->capacity){size_t cap=r->capacity?r->capacity*2:128;fl_pkg_file *f=realloc(r->files,cap*sizeof(*f));if(!f)goto bad;r->files=f;r->capacity=cap;}for(size_t k=0;k<r->count;k++)if(!strcmp(r->files[k].path,path))goto bad;char *copy=strdup(path);if(!copy)goto bad;inode *f=&p->nodes[in];if((f->mode&0170000)!=0100000){free(copy);goto bad;}r->files[r->count++]=(fl_pkg_file){copy,in,(f->flags&1)?f->csize:f->size};}else if(ty!=2&&ty!=3)goto bad;pos+=es;}}free(buf);r->visiting[ino]=0;return 0;bad:free(buf);return fail(r,"Invalid PFS directory entries or read failure");}
static void pfs_free(pfs *p){if(p->nodes)for(uint32_t i=0;i<p->n;i++)free(p->nodes[i].map);free(p->nodes);}
fl_pkg_reader *fl_pkg_open(const char *path,char *error,size_t error_size){if(error&&error_size)snprintf(error,error_size,"Package reader allocation failed");fl_pkg_reader *r=calloc(1,sizeof(*r));if(!r)return NULL;r->pkg.fd=-1;r->active_index=SIZE_MAX;if(pkg_open(&r->pkg,path)){fail(r,"Invalid or unreadable package");goto bad;}struct stat st;if(fstat(r->pkg.fd,&st)||st.st_size<4096||!S_ISREG(st.st_mode)){fail(r,"Package is not a regular file");goto bad;}r->physical_size=(uint64_t)st.st_size;r->base=r->pkg.pfs_offset;if(r->physical_size>INT64_MAX||!within(r->physical_size,r->base,r->pkg.pfs_size)||r->pkg.pfs_size%4096){fail(r,"Package PFS range is invalid");goto bad;}uint8_t h1[32],h2[32],data[96],ek[32],check[32],cid[48]={0};memcpy(cid,r->pkg.header+0x40,36);uint8_t one[4]={0,0,0,1};sha256(one,4,h1);sha256(cid,48,h2);memcpy(data,h1,32);memcpy(data+32,h2,32);memset(data+64,'0',32);sha256(data,96,ek);sha256(ek,32,check);for(unsigned i=0;i<32;i++)check[i]^=ek[i];size_t keys_size=0;uint8_t *keys=pkg_entry(&r->pkg,0x10,&keys_size);int match=keys&&keys_size>=96&&!memcmp(keys+64,check,32);free(keys);if(!match){fail(r,"Unsupported package: requires zero-passcode fPKG");goto bad;}r->raw=(stream){r->pkg.pfs_size,raw_read,r};if(pfs_init(&r->outer,r,&r->raw,ek,!!(b64(r->pkg.header+0x408)&UINT64_C(0x2000000000000000))))goto bad;r->visiting=calloc(r->outer.n,1);if(!r->visiting||walk(&r->outer,0,"",0,1))goto bad;size_t image=SIZE_MAX;for(size_t i=0;i<r->count;i++)if(!strcmp(r->files[i].path,"pfs_image.dat"))image=i;if(image==SIZE_MAX){fail(r,"Package has no pfs_image.dat");goto bad;}file_init(&r->image,&r->outer,r->files[image].inode);if(!(r->image.node->flags&1)||pfsc_init(&r->image_pfsc,&r->image.s)||r->image_pfsc.s.size!=r->image.node->csize){fail(r,"Unsupported or corrupt outer PFSC");goto bad;}for(size_t i=0;i<r->count;i++)free((void*)r->files[i].path);r->count=0;free(r->visiting);r->visiting=NULL;if(pfs_init(&r->inner,r,&r->image_pfsc.s,NULL,0))goto bad;r->visiting=calloc(r->inner.n,1);if(!r->visiting||walk(&r->inner,0,"",0,1))goto bad;if(!r->count){fail(r,"Empty inner PFS");goto bad;}return r;bad:if(error&&error_size)snprintf(error,error_size,"%s",r->error[0]?r->error:"Package reader allocation/read failure");fl_pkg_close(r);return NULL;}
void fl_pkg_close(fl_pkg_reader *r){if(!r)return;pfsc_free(&r->active_pfsc);pfsc_free(&r->image_pfsc);pfs_free(&r->inner);pfs_free(&r->outer);for(size_t i=0;i<r->count;i++)free((void*)r->files[i].path);free(r->files);free(r->visiting);pkg_close(&r->pkg);free(r);}
const char *fl_pkg_error(const fl_pkg_reader *r){return r?r->error:"Invalid package reader";}
const char *fl_pkg_content_id(const fl_pkg_reader *r){return r?r->pkg.content_id:"";}
size_t fl_pkg_file_count(const fl_pkg_reader *r){return r?r->count:0;}
const fl_pkg_file *fl_pkg_files(const fl_pkg_reader *r){return r?r->files:NULL;}
uint32_t fl_pkg_file_mode(const fl_pkg_reader *r,size_t index){return r&&index<r->count&&r->files[index].inode<r->inner.n?r->inner.nodes[r->files[index].inode].mode&0777u:0;}
int fl_pkg_read(fl_pkg_reader *r,size_t i,uint64_t off,void *out,size_t n){if(!r||i>=r->count||(!out&&n))return -1;if(r->error[0])return -1;if(!within(r->files[i].size,off,n))return fail(r,"Read exceeds extracted file length");if(r->active_index!=i){pfsc_free(&r->active_pfsc);file_init(&r->active_file,&r->inner,r->files[i].inode);r->active_index=SIZE_MAX;if((r->active_file.node->flags&1)&&(pfsc_init(&r->active_pfsc,&r->active_file.s)||r->active_pfsc.s.size!=r->active_file.node->csize))return fail(r,"Invalid inner PFSC map");r->active_index=i;}stream *s=(r->active_file.node->flags&1)?&r->active_pfsc.s:&r->active_file.s;if(rd(s,off,out,n))return fail(r,"Corrupt file data/PFSC checksum or source read failure");return 0;}
uint8_t *fl_pkg_metadata_entry(fl_pkg_reader *r,uint32_t id,size_t *n){if(!r||!n)return NULL;return pkg_entry(&r->pkg,id,n);}

int fl_pkg_metadata_present(const fl_pkg_reader *r,uint32_t id){if(!r)return 0;for(int i=0;i<r->pkg.nentries;i++)if(r->pkg.entries[i].id==id)return 1;return 0;}

int fl_pkg_source_stat(const fl_pkg_reader *r,struct stat *out){return r&&out?fstat(r->pkg.fd,out):-1;}
